import "server-only";
import { GraphQLClient } from "graphql-request";

if (!process.env.HYGRAPH_API_URL) {
  throw new Error("HYGRAPH_API_URL is missing from .env.local");
}

const headers: Record<string, string> = {};
if (process.env.HYGRAPH_API_TOKEN) {
  headers["Authorization"] = `Bearer ${process.env.HYGRAPH_API_TOKEN}`;
}

/** Client for published (live) content. Use this for all production reads. */
export const hygraphClient = new GraphQLClient(
  process.env.HYGRAPH_API_URL,
  { headers },
);

// Preview client is initialized lazily — preview URL is optional.
// Call getPreviewClient() inside Next.js Draft Mode handlers only.
const _previewClient = process.env.HYGRAPH_PREVIEW_URL
  ? new GraphQLClient(process.env.HYGRAPH_PREVIEW_URL, { headers })
  : null;

/**
 * Returns the preview client for Next.js Draft Mode.
 * Throws if HYGRAPH_PREVIEW_URL is not set — call only from preview/draft handlers.
 */
export function getPreviewClient(): GraphQLClient {
  if (!_previewClient) {
    throw new Error(
      "HYGRAPH_PREVIEW_URL is missing from .env.local. " +
        "Add it to enable Draft Mode / Content Preview API.",
    );
  }
  return _previewClient;
}

