"use server";

import { hygraphClient, getPreviewClient } from "./client";

/**
 * Run any GraphQL query against your Hygraph content API.
 *
 * Tag results for ISR cache invalidation:
 *   query(doc, vars, { tags: ["article"] })
 *
 * Then call revalidateTag("article") in your webhook handler to bust the cache.
 */
export async function query<T>(
  document: string,
  variables?: Record<string, unknown>,
  options?: { tags?: string[] },
): Promise<T> {
  const tags = options?.tags ?? [];
  return hygraphClient.request<T>(document, variables ?? {}, {
    fetch: (url: RequestInfo | URL, init?: RequestInit) =>
      fetch(url, {
        ...init,
        ...(tags.length > 0 ? { next: { tags } } : {}),
      }),
  });
}

/**
 * Fetch all published entries of a Hygraph content model.
 *
 * `modelPlural` is the auto-generated plural query name from your Hygraph schema
 * (e.g., "articles", "blogPosts"). `fields` is the GraphQL field selection
 * (e.g., "id title slug publishedAt").
 *
 * Results are tagged with `modelPlural` for ISR invalidation.
 */
export async function getEntriesByModel<T>(
  modelPlural: string,
  fields: string,
  variables?: { first?: number; skip?: number; orderBy?: string },
): Promise<T[]> {
  const args: string[] = [];
  if (variables?.first !== undefined) args.push(`first: ${variables.first}`);
  if (variables?.skip !== undefined) args.push(`skip: ${variables.skip}`);
  if (variables?.orderBy) args.push(`orderBy: ${variables.orderBy}`);
  const argStr = args.length > 0 ? `(${args.join(", ")})` : "";

  const document = `query { ${modelPlural}${argStr} { ${fields} } }`;
  const result = await query<Record<string, T[]>>(document, {}, {
    tags: [modelPlural],
  });
  return result[modelPlural] ?? [];
}

/**
 * Fetch a single published entry by `slug` field value.
 * Assumes your content model has a `slug` field.
 * Returns the first match or null.
 *
 * `model` is the singular Hygraph query name (e.g., "article", "blogPost").
 */
export async function getEntryBySlug<T>(
  model: string,
  fields: string,
  slug: string,
): Promise<T | null> {
  const document = `
    query GetBySlug($slug: String!) {
      ${model}(where: { slug: $slug }) {
        ${fields}
      }
    }
  `;
  const result = await query<Record<string, T | null>>(
    document,
    { slug },
    { tags: [model] },
  );
  return result[model] ?? null;
}

/**
 * Fetch a single published entry by its Hygraph entry ID.
 */
export async function getEntryById<T>(
  model: string,
  fields: string,
  id: string,
): Promise<T | null> {
  const document = `
    query GetById($id: ID!) {
      ${model}(where: { id: $id }) {
        ${fields}
      }
    }
  `;
  const result = await query<Record<string, T | null>>(document, { id });
  return result[model] ?? null;
}

/**
 * Fetch a draft entry via the Content Preview API.
 * Use this inside Next.js Draft Mode (`draftMode().isEnabled`) to show unpublished content.
 * Requires HYGRAPH_PREVIEW_URL to be set.
 *
 * Pass a full GraphQL document string — preview results are never cached.
 */
export async function getEntryPreview<T>(
  document: string,
  variables?: Record<string, unknown>,
): Promise<T> {
  return getPreviewClient().request<T>(document, variables ?? {});
}

