import crypto from "crypto";
import { revalidateTag, revalidatePath } from "next/cache";

export interface HygraphWebhookPayload {
  /** The operation that triggered the webhook */
  operation: "PUBLISH" | "UNPUBLISH" | "CREATE" | "UPDATE" | "DELETE";
  data: {
    /** GraphQL type name of the affected model, e.g. "Article", "Product" */
    __typename: string;
    id: string;
    [key: string]: unknown;
  };
}

/**
 * Verifies the Hygraph webhook secret.
 *
 * Configure a custom `gcms-webhook-signature` header in your Hygraph webhook
 * settings and set HYGRAPH_WEBHOOK_SECRET to the same value. Timing-safe
 * comparison prevents oracle attacks on the string compare.
 */
export function verifyWebhookSecret(
  signatureHeader: string,
  secret: string,
): boolean {
  const a = Buffer.from(signatureHeader, "utf8");
  const b = Buffer.from(secret, "utf8");
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

export async function handleHygraphEvent(
  payload: HygraphWebhookPayload,
): Promise<void> {
  // Derive a stable ISR tag from the GraphQL type name.
  // Tag your query calls with this value:
  //   query(doc, vars, { tags: ["article"] })
  const contentType = payload.data.__typename.toLowerCase();

  switch (payload.operation) {
    case "PUBLISH":
    case "UNPUBLISH": {
      revalidateTag(contentType);
      // TODO: Narrow this to specific paths rather than a full-layout revalidation —
      // e.g. revalidatePath(`/${contentType}`) or per-slug if your payload includes one.
      revalidatePath("/", "layout");
      console.log(
        `[hygraph] Revalidated tag "${contentType}" and path "/" on ${payload.operation}`,
      );
      break;
    }
    case "CREATE":
    case "UPDATE":
    case "DELETE": {
      revalidateTag(contentType);
      console.log(
        `[hygraph] Revalidated tag "${contentType}" on ${payload.operation}`,
      );
      break;
    }
    default:
      console.log(`[hygraph] Unhandled operation: ${payload.operation}`);
  }
}

