import { headers } from "next/headers";
import {
  handleHygraphEvent,
  verifyWebhookSecret,
} from "@/infra/hygraph/webhooks";

export async function POST(req: Request) {
  const body = await req.text();
  const headersList = await headers();
  const signatureHeader = headersList.get("gcms-webhook-signature");

  if (!signatureHeader) {
    return new Response("Bad request", { status: 400 });
  }

  if (!process.env.HYGRAPH_WEBHOOK_SECRET) {
    console.error("[hygraph webhook] HYGRAPH_WEBHOOK_SECRET is not set");
    return new Response("Server misconfiguration", { status: 500 });
  }

  if (!verifyWebhookSecret(signatureHeader, process.env.HYGRAPH_WEBHOOK_SECRET)) {
    console.error("[hygraph webhook] Invalid gcms-webhook-signature header");
    return new Response("Unauthorized", { status: 401 });
  }

  // Parse FIRST — malformed JSON is a permanent error (400, no retry).
  let event;
  try {
    event = JSON.parse(body);
  } catch (err: unknown) {
    console.error("[hygraph webhook] Malformed JSON", err);
    return new Response("Bad request", { status: 400 });
  }

  // Handler errors are 500 so Hygraph retries — distinct from 4xx above.
  try {
    await handleHygraphEvent(event);
    return new Response("OK", { status: 200 });
  } catch (err: unknown) {
    console.error("[hygraph webhook] Handler error", err);
    return new Response("Internal error", { status: 500 });
  }
}
